CREATE OR REPLACE FUNCTION public.aviv_create_guest_request(_service_slug text,_name text,_email text,_phone text,_requested timestamptz,_alternative timestamptz,_token_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.services%ROWTYPE; b public.bookings%ROWTYPE; BEGIN SELECT * INTO s FROM public.services WHERE slug=_service_slug AND active AND published FOR SHARE; IF NOT FOUND OR s.price_minor<=0 THEN RAISE EXCEPTION 'Service unavailable'; END IF; IF length(trim(_name)) NOT BETWEEN 2 AND 100 OR length(_email)>254 OR _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(coalesce(_phone,''))>30 OR _token_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid booking details'; END IF; IF _requested<=now() OR _requested>now()+interval '180 days' OR (_alternative IS NOT NULL AND (_alternative<=now() OR _alternative>now()+interval '180 days' OR _alternative=_requested)) THEN RAISE EXCEPTION 'Invalid requested time'; END IF; INSERT INTO public.bookings(public_reference,client_name,client_email,client_phone,service_id,price_minor,currency,requested_start,alternative_start,time_zone,request_expires_at,service_title_snapshot,duration_minutes_snapshot,policy_acknowledged_at) VALUES('AVIV-'||replace(gen_random_uuid()::text,'-',''),trim(_name),lower(trim(_email)),nullif(trim(_phone),''),s.id,s.price_minor,s.currency,_requested,_alternative,'Africa/Lagos',now()+interval '30 minutes',s.title,s.duration_minutes,now()) RETURNING * INTO b; INSERT INTO public.booking_access_tokens(booking_id,token_hash,purpose,expires_at) VALUES(b.id,_token_hash,'manage',now()+interval '30 days'); RETURN jsonb_build_object('id',b.id,'reference',b.public_reference,'price_minor',b.price_minor,'currency',b.currency,'expires_at',b.request_expires_at); END $$; REVOKE ALL ON FUNCTION public.aviv_create_guest_request(text,text,text,text,timestamptz,timestamptz,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.aviv_create_guest_request(text,text,text,text,timestamptz,timestamptz,text) TO service_role;